import json,glob,os
for f in glob.glob('factors/*.json'):
 if f.endswith('factor_ensemble.json'): continue
 try:
  d=json.load(open(f)); m=d.get('validation_metrics',d.get('metrics',{}))
  print(os.path.basename(f), d.get('status'), 'IC',m.get('ic_10d',m.get('mean_ic_10d',m.get('ic'))), 'ICIR',m.get('icir_10d',m.get('icir')), 'turn',m.get('rank_turnover'))
 except Exception as e: print('ERR',f,e)
PY

